import json
from pathlib import Path

def md(text): return {'cell_type':'markdown','metadata':{},'source':text.splitlines(keepends=True)}
def code(text): return {'cell_type':'code','execution_count':None,'metadata':{},'outputs':[],'source':text.splitlines(keepends=True)}
cells=[
md('# LogiTrack Predictive Analytics\n\nThis Colab-ready notebook develops and evaluates models that predict delivery duration in minutes from historical logistics characteristics.'),
md('## 1. Setup\n\nThe notebook uses fixed random seeds. Upload `amazon_delivery.csv` to the Colab session before running the data-loading cell.'),
code('!pip -q install pandas numpy scikit-learn joblib matplotlib seaborn\nimport pandas as pd, numpy as np, joblib\nfrom sklearn.compose import ColumnTransformer\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder, StandardScaler\nfrom sklearn.impute import SimpleImputer\nfrom sklearn.dummy import DummyRegressor\nfrom sklearn.linear_model import Ridge\nfrom sklearn.ensemble import RandomForestRegressor, GradientBoostingRegressor\nfrom sklearn.metrics import mean_absolute_error, mean_squared_error, r2_score\nSEED=42'),
md('## 2. Data loading and inspection'),
code("df=pd.read_csv('amazon_delivery.csv')\nprint(df.shape)\ndisplay(df.head())\ndisplay(df.dtypes)\ndisplay(df.isna().sum())\nprint('Exact duplicate rows:',df.duplicated().sum())"),
md('## 3. Exploratory analysis\n\nInspect the delivery-time target, categorical comparisons, missingness, and coordinate quality before choosing features.'),
code("display(df['Delivery_Time'].describe())\ndisplay(df.groupby('Traffic')['Delivery_Time'].agg(['count','mean','median']).sort_values('mean',ascending=False))\ndisplay(df.groupby('Weather')['Delivery_Time'].agg(['count','mean','median']).sort_values('mean',ascending=False))"),
md('## 4. Feature engineering and leakage control\n\n`Pickup_Time` is excluded because it can occur after order placement. Haversine distance uses valid coordinates. The distance cap is learned from training data only.'),
code("def haversine(lat1,lon1,lat2,lon2):\n r=6371.; p1,p2=np.radians(lat1),np.radians(lat2); dp=np.radians(lat2-lat1); dl=np.radians(lon2-lon1); a=np.sin(dp/2)**2+np.cos(p1)*np.cos(p2)*np.sin(dl/2)**2; return 2*r*np.arcsin(np.sqrt(np.clip(a,0,1)))\ndf['Order_Date']=pd.to_datetime(df['Order_Date'],errors='coerce')\nfor c in ['Agent_Age','Agent_Rating','Store_Latitude','Store_Longitude','Drop_Latitude','Drop_Longitude','Delivery_Time']: df[c]=pd.to_numeric(df[c],errors='coerce')\nvalid=df[['Store_Latitude','Store_Longitude','Drop_Latitude','Drop_Longitude']].notna().all(axis=1)&df.Store_Latitude.between(-90,90)&df.Drop_Latitude.between(-90,90)&df.Store_Longitude.between(-180,180)&df.Drop_Longitude.between(-180,180)\ndf=df.loc[valid&df.Order_Date.notna()&df.Delivery_Time.notna()].copy()\ndf['Distance_km']=haversine(df.Store_Latitude,df.Store_Longitude,df.Drop_Latitude,df.Drop_Longitude)\ndf['Order_Hour']=pd.to_datetime(df.Order_Time,format='%H:%M:%S',errors='coerce').dt.hour.fillna(-1)\ndf['Day_of_Week']=df.Order_Date.dt.dayofweek\nfor c in ['Weather','Traffic','Vehicle','Area','Category']: df[c]=df[c].fillna('Unknown').astype(str).str.strip().replace({'NaN':'Unknown','nan':'Unknown','':'Unknown'})"),
md('## 5. Chronological split and preprocessing'),
code("df=df.sort_values('Order_Date').reset_index(drop=True)\nsplit_date=df.Order_Date.iloc[int(len(df)*.8)]\ntrain,test=df[df.Order_Date<split_date].copy(),df[df.Order_Date>=split_date].copy()\ncap=train.Distance_km.quantile(.99)\nfor x in [train,test]: x['Distance_Model_km']=x.Distance_km.clip(upper=cap)\nnum=['Agent_Age','Agent_Rating','Distance_Model_km','Order_Hour','Day_of_Week']; cat=['Weather','Traffic','Vehicle','Area','Category']; features=num+cat\npre=ColumnTransformer([('num',Pipeline([('impute',SimpleImputer(strategy='median')),('scale',StandardScaler())]),num),('cat',Pipeline([('impute',SimpleImputer(strategy='most_frequent')),('onehot',OneHotEncoder(handle_unknown='ignore',sparse_output=False))]),cat)])"),
md('## 6. Candidate models and held-out evaluation'),
code("models={'Dummy':DummyRegressor(),'Ridge':Pipeline([('pre',pre),('m',Ridge(alpha=3))]),'Random Forest':Pipeline([('pre',pre),('m',RandomForestRegressor(n_estimators=160,min_samples_leaf=3,max_features=.8,n_jobs=-1,random_state=SEED))]),'Gradient Boosting':Pipeline([('pre',pre),('m',GradientBoostingRegressor(n_estimators=220,learning_rate=.045,max_depth=3,min_samples_leaf=8,random_state=SEED))])}\nresults=[]; fitted={}\nfor name,m in models.items():\n m.fit(train[features],train.Delivery_Time); p=m.predict(test[features]); results.append([name,mean_absolute_error(test.Delivery_Time,p),mean_squared_error(test.Delivery_Time,p)**.5,r2_score(test.Delivery_Time,p)]); fitted[name]=m\nresults=pd.DataFrame(results,columns=['Model','MAE','RMSE','R2']).sort_values('MAE'); display(results)"),
md('## 7. Diagnostics, interpretation, and export\n\nSelect the best model by validation criteria without tuning on the untouched test set in later refinements. Importance measures predictive contribution, not causation.'),
code("best_name=results.iloc[0].Model; best=fitted[best_name]; pred=best.predict(test[features])\nimport matplotlib.pyplot as plt\nplt.scatter(test.Delivery_Time,pred,alpha=.15); plt.xlabel('Actual minutes'); plt.ylabel('Predicted minutes'); plt.title('Held-out actual vs predicted'); plt.show()\nplt.hist(test.Delivery_Time-pred,bins=40); plt.title('Held-out residual distribution'); plt.show()\njoblib.dump(best,'delivery_time_pipeline.joblib')\nprint('Selected model:',best_name,'Distance cap:',cap)"),
md('## 8. Conclusion\n\nReport only metrics produced by the executed notebook. Explain geographical anomalies, model uncertainty, the historical scope of the data, and the lack of sufficient date coverage for demand forecasting.')]
notebook={'cells':cells,'metadata':{'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'},'language_info':{'name':'python','version':'3'}},'nbformat':4,'nbformat_minor':5}
Path(__file__).with_name('LogiTrack_Predictive_Analytics.ipynb').write_text(json.dumps(notebook,indent=1),encoding='utf-8')
